// Creates and returns a dynamically allocated game instance initialized with a given word.
struct game_instance *helper_create_game_instance(const char *word) {
    if (word == NULL) return NULL;
    struct game_instance *game = malloc(sizeof(struct game_instance));
    if (game == NULL) return NULL;
    init_game_instance(game, word);
    return game;
}

// Creates and returns a dynamically allocated game instance with a random word from a given array.
struct game_instance *helper_create_game_from_words(const char **words, int num_words) {
    if (words == NULL || num_words <= 0) return NULL;
    srand(time(NULL));
    struct game_instance game = new_game_from_words(words, num_words);
    struct game_instance *game_ptr = malloc(sizeof(struct game_instance));
    if (game_ptr == NULL) return NULL;
    *game_ptr = game;
    return game_ptr;
}

// Resets a game instance to initial state with a new word, clearing guesses and incorrect count.
void helper_reset_game_instance(struct game_instance *game, const char *word) {
    if (game == NULL || word == NULL) return;
    init_game_instance(game, word);
}


